<script>
document.addEventListener('DOMContentLoaded', function () {
  var ethicButtons = document.querySelectorAll('.about3-ethic button');
  ethicButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      var willOpen = button.getAttribute('aria-expanded') !== 'true';
      ethicButtons.forEach(function (item) { item.setAttribute('aria-expanded', 'false'); });
      button.setAttribute('aria-expanded', String(willOpen));
    });
  });

  var navLinks = Array.from(document.querySelectorAll('.about3-nav a'));
  var sections = navLinks.map(function (link) { return document.querySelector(link.getAttribute('href')); }).filter(Boolean);
  if ('IntersectionObserver' in window) {
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        navLinks.forEach(function (link) {
          link.classList.toggle('active', link.getAttribute('href') === '#' + entry.target.id);
        });
      });
    }, { rootMargin: '-25% 0px -65% 0px', threshold: 0 });
    sections.forEach(function (section) { observer.observe(section); });
  }
});
</script>
</body>
</html>
